{
  "name": "oc-plugin-view",
  "version": "0.2.1",
  "description": "See every loaded OpenCode server plugin in the sidebar, without opening a dialog.",
  "type": "module",
  "license": "MIT",
  "author": "nathwn12",
  "homepage": "https://github.com/nathwn12/oc-collections/tree/main/packages/oc-plugin-view",
  "bugs": "https://github.com/nathwn12/oc-collections/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nathwn12/oc-collections.git",
    "directory": "packages/oc-plugin-view"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "tui",
    "sidebar",
    "typescript",
    "tooling",
    "server"
  ],
  "exports": {
    ".": {
      "types": "./src/index.ts",
      "import": "./dist/index.js"
    },
    "./tui": {
      "types": "./src/tui.tsx",
      "import": "./dist/tui.js"
    }
  },
  "files": [
    "dist",
    "src",
    "README.md",
    "LICENSE",
    "CHANGELOG.md",
    "assets",
    "!src/**/*.test.*"
  ],
  "engines": {
    "node": ">=22",
    "bun": ">=1.4.0"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "compile": "bun scripts/build.ts",
    "check": "bun run typecheck && bun test",
    "check:dist": "bun run compile && git diff --exit-code -- dist",
    "prepublishOnly": "node ../../scripts/check-version-cell.mjs . && bun run check && bun run compile"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode/plugin": "^2.3.0"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.8.0",
    "@opentui/solid": ">=0.8.0",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/plugin": "2.3.0",
    "@opentui/core": "0.9.0",
    "@opentui/solid": "0.9.0",
    "@types/bun": "^1.4.4",
    "solid-js": "1.9.19",
    "typescript": "^7.0.2"
  }
}

// @bun
// src/index.ts
import { Plugin } from "@opencode/plugin";
var src_default = Plugin.define({
  id: "oc-plugin-view.host",
  setup() {}
});
export {
  src_default as default
};

import { Plugin } from "@opencode/plugin"

// OpenCode loads the package root from opencode.jsonc and discovers the
// separate ./tui export for the terminal UI. This server-side compatibility
// entrypoint is deliberately inert: all visible behavior lives in src/tui.
export default Plugin.define({
  id: "oc-plugin-view.host",
  setup() {},
})
